// ------------------------------------------------------------------------------
//  AIEngineTypes.cs
//
//  Shared types of the AI engine. They are part of the engine's contract
//  and do not depend on any specific brain, so they are distributed
//  with the plugin and are NOT generated by the editor.
//
//  Add this file only once to the Unity project, alongside the rest of
//  the engine code.
// ---------------------------------------------------------------------------

/// <summary>
/// Result of executing an NPC action. The numeric values must
/// match the conversion done by the native layer in AIEngineAPI.cpp.
/// </summary>
public enum NodeState
{
    /// <summary>The action could not be performed.</summary>
    Failure = 0,

    /// <summary>The action has been completed successfully.</summary>
    Success = 1,

    /// <summary>
    /// The action is still being executed and needs more frames
    /// to complete (for example, a movement or an animation).
    /// The tree respects this state and does not consider the action finished.
    /// </summary>
    Running = 2
}
